/* Frozen Win10 tables for options_table (generated by the scripts in gen/, see EVIDENCE.md). */
#ifndef OT_TAB_H
#define OT_TAB_H
typedef struct { int opt; const char *exp; } ot_stab_row;
extern const ot_stab_row ot_stab[];
extern const int ot_stab_n;
/* Round-trip matrix (ot_rt_matrix.c, generated by gen/gen_rtab.py): same row type, different token grammar. */
extern const ot_stab_row ot_rtab[];
extern const int ot_rtab_n;

/* Query matrix: one row per (option, handle kind, A/W). Each probe is "r,e,l" or "" (not run).
 *   q0: buffer NULL, *len 0          q1: 4096-byte buffer
 *   q2: buffer, *len = q1's *len     q3: buffer, *len = 1           (q2/q3 only when q1 succeeded with 0 < len < 4096)
 * flags: OTQ_VOLATILE_L1 = q1/q2/q3 length depends on the environment (path, port, time): checked with ot_qvol rules. */
typedef struct {
    int opt; char kind; char w;
    int r0; unsigned e0, l0;
    int r1; unsigned e1, l1;
    int r2; unsigned e2, l2;     /* r2 == -1: not run */
    int r3; unsigned e3, l3;
    unsigned flags;
    const char *data;           /* q1 bytes (hex) when frozen, else NULL */
} ot_qrow;
#define OTQ_VOL_LEN   1u   /* q1..q3 lengths environment-dependent: only the r/e pattern is checked */
#define OTQ_VOL_DATA  2u   /* value environment-dependent: data not frozen */
#define OTQ_VOL_ALL   4u   /* whole row is environment/timing dependent: t_note only */
extern const ot_qrow ot_qtab[];
extern const int ot_qtab_n;
#endif
